ring":"Mechanical CAD/CAM/CAE","batch":{"code":"SJV-MECH-06-2026-B1","name":"Shivajinagar - MECH - Creo - Batch 1","start_date":"2026-11-26","end_date":"2027-01-25","max_capacity":40}},{"code":"MECH-INVENTOR","title":"Inventor","description":"Source fee structure: MECHANICAL FEE STRUCTURE.pdf. Listed duration: 60 days. Government certification charges may be additional.","duration_months":2,"total_fee":"15000.00","field_of_engineering":"Mechanical CAD/CAM/CAE","batch":{"code":"SJV-MECH-07-2026-B1","name":"Shivajinagar - MECH - Inventor - Batch 1","start_date":"2026-11-26","end_date":"2027-01-25","max_capacity":40}},{"code":"MECH-NX-CAD","title":"UG-NX (Unigraphics)","description":"Source fee structure: MECHANICAL FEE STRUCTURE.pdf. Listed duration: 60 days. Government certification charges may be additional.","duration_months":2,"total_fee":"12000.00","field_of_engineering":"Mechanical CAD/CAM/CAE","batch":{"code":"SJV-MECH-05-2026-B1","name":"Shivajinagar - MECH - UG-NX (Unigraphics) - Batch 1","start_date":"2026-11-26","end_date":"2027-01-25","max_capacity":40}},{"code":"MECH-SOLIDWORKS","title":"Solid Works","description":"Source fee structure: MECHANICAL FEE STRUCTURE.pdf. Listed duration: 60 days. Government certification charges may be additional.","duration_months":2,"total_fee":"12000.00","field_of_engineering":"Mechanical CAD/CAM/CAE","batch":{"code":"SJV-MECH-04-2026-B1","name":"Shivajinagar - MECH - Solid Works - Batch 1","start_date":"2026-11-26","end_date":"2027-01-25","max_capacity":40}},{"code":"MEP-REVIT-MEP","title":"Revit MEP","description":"Source fee structure: CIVIL FEES STRUCTURE.pdf. Listed duration: 2 months. These are basic fees; management discounts may apply.","duration_months":2,"total_fee":"16000.00","field_of_engineering":"Civil CAD","batch":{"code":"SJV-CIVIL-08-2026-B1","name":"Shivajinagar - CIVIL - Revit MEP - Batch 1","start_date":"2026-11-26","end_date":"2027-01-26","max_capacity":40}}]}$catalog$::jsonb;
    v_branch accounts_branch%ROWTYPE;
    v_course academics_course%ROWTYPE;
    v_batch academics_batch%ROWTYPE;
    v_item jsonb;
    v_branch_id uuid;
    v_course_id uuid;
    v_batch_id uuid;
    v_batch_data jsonb;
BEGIN
    INSERT INTO accounts_branch (
        id, created_at, updated_at, is_deleted, deleted_at, version,
        code, name, city, address, phone, email
    ) VALUES (
        gen_random_uuid(), now(), now(), false, NULL, 1,
        v_payload->'branch'->>'code',
        v_payload->'branch'->>'name',
        v_payload->'branch'->>'city',
        v_payload->'branch'->>'address',
        v_payload->'branch'->>'phone',
        v_payload->'branch'->>'email'
    ) ON CONFLICT (code) DO NOTHING;

    SELECT * INTO v_branch
      FROM accounts_branch
     WHERE code = v_payload->'branch'->>'code';
    IF NOT FOUND THEN
        RAISE EXCEPTION 'Could not find or create the Shivajinagar branch.';
    END IF;
    IF v_branch.is_deleted OR v_branch.name IS DISTINCT FROM (v_payload->'branch'->>'name') THEN
        RAISE EXCEPTION 'Branch code SHIVAJINAGAR is deleted or belongs to a different branch.';
    END IF;
    v_branch_id := v_branch.id;

    FOR v_item IN
        SELECT value FROM jsonb_array_elements(v_payload->'courses') AS items(value)
    LOOP
        SELECT * INTO v_course
          FROM academics_course
         WHERE code = v_item->>'code';

        IF NOT FOUND THEN
            INSERT INTO academics_course (
                id, created_at, updated_at, is_deleted, deleted_at, version,
                code, title, description, duration_months, total_fee, field_of_engineering
            ) VALUES (
                gen_random_uuid(), now(), now(), false, NULL, 1,
                v_item->>'code', v_item->>'title', v_item->>'description',
                (v_item->>'duration_months')::integer,
                (v_item->>'total_fee')::numeric,
                NULLIF(v_item->>'field_of_engineering', '')
            ) ON CONFLICT (code) DO NOTHING;
            SELECT * INTO v_course
              FROM academics_course
             WHERE code = v_item->>'code';
        END IF;

        IF NOT FOUND OR v_course.is_deleted THEN
            RAISE EXCEPTION 'Course code % is missing or soft-deleted.', v_item->>'code';
        END IF;
        v_course_id := v_course.id;

        IF v_course.title IS DISTINCT FROM (v_item->>'title')
           OR v_course.description IS DISTINCT FROM (v_item->>'description')
           OR v_course.duration_months IS DISTINCT FROM (v_item->>'duration_months')::integer
           OR v_course.total_fee IS DISTINCT FROM (v_item->>'total_fee')::numeric
           OR v_course.field_of_engineering IS DISTINCT FROM NULLIF(v_item->>'field_of_engineering', '')
        THEN
            RAISE EXCEPTION 'Course code % already exists with different details; no changes were committed.', v_item->>'code';
        END IF;

        v_batch_data := v_item->'batch';
        SELECT * INTO v_batch
          FROM academics_batch
         WHERE code = v_batch_data->>'code';

        IF FOUND THEN
            IF v_batch.is_deleted
               OR v_batch.course_id <> v_course_id
               OR v_batch.branch_id <> v_branch_id
               OR v_batch.name IS DISTINCT FROM (v_batch_data->>'name')
               OR v_batch.start_date IS DISTINCT FROM (v_batch_data->>'start_date')::date
               OR v_batch.end_date IS DISTINCT FROM (v_batch_data->>'end_date')::date
               OR v_batch.max_capacity IS DISTINCT FROM (v_batch_data->>'max_capacity')::integer
            THEN
                RAISE EXCEPTION 'Batch code % is already used by different data.', v_batch_data->>'code';
            END IF;
        ELSE
            IF EXISTS (
                SELECT 1 FROM academics_batch b
                 WHERE b.course_id = v_course_id
                   AND b.branch_id = v_branch_id
                   AND b.is_deleted = false
            ) THEN
                RAISE EXCEPTION 'Course % already has a Shivajinagar batch with a different code.', v_item->>'code';
            END IF;

            INSERT INTO academics_batch (
                id, created_at, updated_at, is_deleted, deleted_at, version,
                code, name, start_date, end_date, max_capacity, course_id, branch_id
            ) VALUES (
                gen_random_uuid(), now(), now(), false, NULL, 1,
                v_batch_data->>'code', v_batch_data->>'name',
                (v_batch_data->>'start_date')::date,
                (v_batch_data->>'end_date')::date,
                (v_batch_data->>'max_capacity')::integer,
                v_course_id, v_branch_id
            ) ON CONFLICT (code) DO NOTHING;

            SELECT * INTO v_batch
              FROM academics_batch
             WHERE code = v_batch_data->>'code';
            IF NOT FOUND OR v_batch.is_deleted
               OR v_batch.course_id <> v_course_id OR v_batch.branch_id <> v_branch_id
            THEN
                RAISE EXCEPTION 'Could not create batch code % consistently.', v_batch_data->>'code';
            END IF;
        END IF;
    END LOOP;
END
$seed$;

COMMIT;

SELECT b.code AS branch_code,
       COUNT(DISTINCT c.id) AS imported_courses,
       COUNT(DISTINCT bt.id) AS branch_batches
  FROM accounts_branch b
  LEFT JOIN academics_batch bt
    ON bt.branch_id = b.id AND bt.is_deleted = false
  LEFT JOIN academics_course c
    ON c.id = bt.course_id AND c.is_deleted = false
   AND c.description LIKE 'Source fee structure:%'
 WHERE b.code = 'SHIVAJINAGAR' AND b.is_deleted = false
 GROUP BY b.code;
